    return sum(sieve)

def solve(n):
    """Return the number of primes strictly less than n using a segmented sieve.
    Works efficiently for large n without allocating O(n) memory.
    """
    import math
    if n <= 2:
        return 0
    limit = int(math.isqrt(n - 1))
    # simple sieve for base primes up to sqrt(n)
    base = bytearray(b'\x01') * (limit + 1)
    if limit >= 0:
        base[0] = 0
    if limit >= 1:
        base[1] = 0
    for p in range(2, int(math.isqrt(limit)) + 1):
        if base[p]:
            start = p * p
            step = p
            base[start:limit+1:step] = b'\x00' * ((limit - start) // step + 1)
    base_primes = [i for i, is_p in enumerate(base) if is_p]
    # segmented sieve
    segment_size = max(limit, 32768)
    count = 0
    low = 2
    while low < n:
        high = min(low + segment_size, n)
        segment = bytearray(b'\x01') * (high - low)
        for p in base_primes:
            # find the first multiple of p in [low, high)
            start = ((low + p - 1) // p) * p
            if start < p * p:
                start = p * p
            for multiple in range(start, high, p):
                segment[multiple - low] = 0
        # exclude numbers less than 2 if they appear in the first segment
        if low == 2:
            if 0 >= low and 0 < high:
                segment[0 - low] = 0
            if 1 >= low and 1 < high:
                segment[1 - low] = 0
        count += sum(segment)
        low = high
    return count

