def solve(mat):
    """Return the determinant of an integer square matrix using the Bareiss algorithm.
    The algorithm performs exact integer arithmetic and runs in O(n^3).
    An empty matrix has determinant 1.
    """
    # Handle empty matrix
    if not mat:
        return 1
    n = len(mat)
    # Verify that the matrix is square; if not, treat as invalid and return 0
    for row in mat:
        if len(row) != n:
            return 0
    # Make a deep copy to avoid mutating input
    a = [list(row) for row in mat]
    det_sign = 1
    for k in range(n - 1):
        # Pivot selection: if pivot is zero, swap with a row below that has a non‑zero element in the same column
        if a[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if a[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0  # Singular matrix
            a[k], a[swap_row] = a[swap_row], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        prev_pivot = a[k - 1][k - 1] if k > 0 else 1
        # Bareiss update for the submatrix
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                a[i][j] = (a[i][j] * pivot - a[i][k] * a[k][j]) // prev_pivot
        # Zero out the column below the pivot (optional for clarity)
        for i in range(k + 1, n):
            a[i][k] = 0
    return det_sign * a[n - 1][n - 1]

