def solve(path):
    """Simplify an absolute Unix path.
    If the input does not start with '/', it's returned unchanged.
    """
    if not path:
        return ''
    if not path.startswith('/'):
        return path
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    result = '/' + '/'.join(stack)
    return result if result != '' else '/'

