def solve(mat):
    """Return determinant using Bareiss algorithm."""
    if not mat:
        return 1
    n = len(mat)
    a = [list(row) for row in mat]
    det_sign = 1
    for k in range(n - 1):
        if a[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if a[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0
            a[k], a[swap] = a[swap], a[k]
            det_sign = -det_sign
        pivot = a[k][k]
        prev = a[k-1][k-1] if k>0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                a[i][j] = (a[i][j]*pivot - a[i][k]*a[k][j]) // prev
        for i in range(k+1, n):
            a[i][k] = 0
    return det_sign * a[n-1][n-1]

