def solve(tokens):
    def trunc_div(a, b):
        q = a // b
        if (a ^ b) < 0 and a % b != 0:
            q += 1
        return q
    ops={'+' ,'-','*','/'}
    stack=[]
    for token in tokens:
        if token in ops:
            b=stack.pop();a=stack.pop()
            if token=='+':res=a+b
            elif token=='-':res=a-b
            elif token=='*':res=a*b
            else:res=trunc_div(a,b)
            stack.append(res)
        else:
            val=token if isinstance(token,int) else int(token)
            stack.append(val)
    return stack[-1] if stack else 0

