def solve(weights, values, capacity):
    # 0/1 knapsack DP: dp[c] = max value for capacity c
    if capacity < 0:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        # traverse capacities descending to avoid reuse
        for c in range(capacity, w - 1, -1):
            if dp[c - w] + v > dp[c]:
                dp[c] = dp[c - w] + v
    return dp[capacity]

