def solve(words, width):
    """Greedy word wrap.
    Packs words into lines separated by a single space. Each line's length must not exceed `width`.
    If `width` is non-positive, return an empty list (no lines can be formed).
    """
    if not words:
        return []
    if width <= 0:
        return []
    lines = []
    current = []
    cur_len = 0
    for w in words:
        if not current:
            current.append(w)
            cur_len = len(w)
        else:
            prospective = cur_len + 1 + len(w)
            if prospective <= width:
                current.append(w)
                cur_len = prospective
            else:
                lines.append(' '.join(current))
                current = [w]
                cur_len = len(w)
    if current:
        lines.append(' '.join(current))
    return lines

