def solve(grid):
    """Count islands in a possibly ragged binary grid.
    Cells with value 1 are considered land. Connectivity is 4-directional.
    The grid may have rows of different lengths; out‑of‑bounds indices are ignored.
    """
    if not grid:
        return 0
    visited = set()
    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            # check bounds for current row
            if i < 0 or i >= len(grid):
                continue
            if j < 0 or j >= len(grid[i]):
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i, j))
            # neighbors
            stack.append((i-1, j))
            stack.append((i+1, j))
            stack.append((i, j-1))
            stack.append((i, j+1))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

